import 'package:flutter/material.dart';

void main() {
  runApp(const PW());
  }

  // ================= ACCOUNT =================

  class Account {
    String name;
      String id;
        String password;

          Account({
              required this.name,
                  required this.id,
                      required this.password,
                        });
                        }

                        // Demo accounts
                        final List<Account> accounts = [
                          Account(
                              name: 'Sarthi',
                                  id: 'sarthi123',
                                      password: '123456',
                                        ),
                                          Account(
                                              name: 'Rahul',
                                                  id: 'rahul123',
                                                      password: '123456',
                                                        ),
                                                          Account(
                                                              name: 'Aman',
                                                                  id: 'aman123',
                                                                      password: '123456',
                                                                        ),
                                                                        ];

                                                                        // ================= APP =================

                                                                        class PW extends StatelessWidget {
                                                                          const PW({super.key});

                                                                            @override
                                                                              Widget build(BuildContext context) {
                                                                                  return MaterialApp(
                                                                                        debugShowCheckedModeBanner: false,
                                                                                              title: 'PW Chat',
                                                                                                    theme: ThemeData(
                                                                                                            colorScheme: ColorScheme.fromSeed(
                                                                                                                      seedColor: Colors.green,
                                                                                                                              ),
                                                                                                                                      useMaterial3: true,
                                                                                                                                            ),
                                                                                                                                                  home: const LoginPage(),
                                                                                                                                                      );
                                                                                                                                                        }
                                                                                                                                                        }

                                                                                                                                                        // ================= LOGIN =================

                                                                                                                                                        class LoginPage extends StatefulWidget {
                                                                                                                                                          const LoginPage({super.key});

                                                                                                                                                            @override
